package com.johnny.hotel.invoice;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/finance/operations") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')") public class FinanceReadController{private final FinanceReadService service;@GetMapping("/{domain}")public Result<PageResult<FinanceOperationalRecord>> read(@PathVariable String domain,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize,@RequestParam(required=false)Integer size){return Result.success(service.read(domain,page,pageSize!=null?pageSize:size));}}
